<?php
defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Meu RH';require APPPATH.'views/admin/includes/native_company_layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'staff/hr_mine');
$hidden=function(string $action)use($esc,$company_hr_csrf,$request_key):void{foreach(['action'=>$action,'company_hr_csrf'=>$company_hr_csrf,'request_key'=>$request_key] as $k=>$v)echo '<input type="hidden" name="'.$esc($k).'" value="'.$esc($v).'">';};
?>
<section class="company-settings-card"><h1>Meu RH nesta empresa</h1><p>Treinamentos, materiais e orientações do seu vínculo ativo.</p>
<?php if($error!==null){?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><?php } ?>
<?php if($result!==null){?><p role="status" class="alert alert-info">Tentativa confirmada. Resultado: <?= (int)$result['score']; ?>%. <?= $result['passed']?'Aprovado.':'Confira o limite de tentativas antes de reenviar.'; ?></p><?php } ?>
<h2>Avisos privados</h2><?php foreach($notices as $n){?><article><h3><?= $esc($n['title']); ?></h3><p><?= $n['event']==='assigned'?'Você recebeu uma atribuição de treinamento.':'O prazo do treinamento chegou.'; ?> <?= $esc($n['scheduled_at']); ?> UTC.</p><?php if($n['read_at']===null){echo form_open($url);$hidden('notice_read');?><input type="hidden" name="notice_id" value="<?= (int)$n['id']; ?>"><button type="submit">Marcar como lido</button><?= form_close(); ?><?php } ?></article><?php } ?>
<h2>Treinamentos</h2><?php foreach($assignments as $r){?><details class="hr-my-assignment" data-assignment-id="<?= (int)$r['id']; ?>"><summary><?= $esc($r['course']['title']); ?> — <?= $esc(['assigned'=>'Aguardando respostas','passed'=>'Aprovado','failed'=>'Tentativas encerradas','cancelled'=>'Cancelado'][$r['state']]??$r['state']); ?></summary><p><?= nl2br($esc($r['course']['description'])); ?></p><p>Prazo: <?= $esc($r['due_at']); ?> UTC · fuso de origem <?= $esc($r['timezone']); ?>. Aprovação: <?= (int)$r['course']['pass_percent']; ?>%. Tentativas: <?= (int)$r['attempt_count']; ?>/<?= (int)$r['course']['max_attempts']; ?>.</p>
<?php if($r['state']!=='cancelled'){?><ul><?php foreach($r['materials'] as $f){?><li><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'staff/hr_mine_file?assignment='.$r['id'].'&file='.$f['id'])); ?>">Material #<?= (int)$f['id']; ?></a></li><?php } ?></ul><?php } ?>
<?php if($r['state']==='assigned'&&$r['due_at']>gmdate('Y-m-d H:i:s')){echo form_open($url,['class'=>'hr-training-response']);$hidden('training_submit');?><input type="hidden" name="assignment_id" value="<?= (int)$r['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$r['revision']; ?>"><?php foreach($r['course']['questions'] as $n=>$q){?><fieldset><legend><?= ($n+1).'. '.$esc($q['question']); ?></legend><?php foreach($q['choices'] as $choice=>$label){?><label style="display:block"><input type="radio" name="answers[<?= (int)$n; ?>]" value="<?= (int)$choice; ?>" required> <?= $esc($label); ?></label><?php } ?></fieldset><?php } ?><button type="submit">Confirmar respostas desta tentativa</button><?= form_close(); ?><?php } ?></details><?php } ?>
<h2>Orientações publicadas</h2><?php foreach($articles as $r){?><details><summary><?= $esc($r['title']); ?></summary><p><?= nl2br($esc($r['body'])); ?></p></details><?php } ?></section>
